#!/usr/bin/env python3
"""Render and validate manifest-managed agent instruction and labeler surfaces."""

from pathlib import Path

GENERATED_DOCS_HEADER = (
    "<!-- Generated by `python3 scripts/agent-surface.py sync` from {sources}; "
    "edit these source files, not this file. -->"
)
SKILL_LABELER_BEGIN = "# BEGIN GENERATED SKILLS LABELS"
SKILL_LABELER_END = "# END GENERATED SKILLS LABELS"


def _repo_path(repo_root: Path, value: object, description: str) -> tuple[Path | None, str | None]:
    if not isinstance(value, str) or not value:
        return None, f"{description} must be a non-empty repository-relative path"
    relative = Path(value)
    if relative.is_absolute() or ".." in relative.parts:
        return None, f"{description} must stay inside the repository: {value}"
    root = repo_root.resolve()
    path = root / relative
    try:
        path.resolve(strict=False).relative_to(root)
    except ValueError:
        return None, f"{description} resolves outside the repository: {value}"
    return path, None


def _instruction_outputs(
    repo_root: Path, manifest: dict[str, object]
) -> tuple[dict[Path, str], list[str]]:
    outputs: dict[Path, str] = {}
    errors: list[str] = []
    source_value = manifest.get("canonical_instructions")
    tools = manifest.get("tools", {})
    if not isinstance(tools, dict):
        return outputs, ["Manifest tools must be an object"]
    has_declared_docs = any(
        isinstance(config, dict) and config.get("docs")
        for config in tools.values()
    )
    if source_value is None:
        if has_declared_docs:
            errors.append("Manifest canonical_instructions is required when tool docs are declared")
        return outputs, errors

    source, error = _repo_path(repo_root, source_value, "canonical_instructions")
    if error:
        return outputs, [error]
    if source is None or not source.is_file():
        return outputs, [f"Canonical instruction source not found: {source_value}"]
    source_name = source.relative_to(repo_root.resolve()).as_posix()
    try:
        source_text = source.read_text(encoding="utf-8").rstrip()
    except OSError as exception:
        return outputs, [f"Cannot read canonical instruction source {source_value}: {exception}"]

    for tool_name, config in tools.items():
        if not isinstance(config, dict):
            errors.append(f"Manifest tool {tool_name!r} must be an object")
            continue
        documents = config.get("docs", [])
        if not isinstance(documents, list):
            errors.append(f"Manifest docs for {tool_name!r} must be a list")
            continue
        addendum_text: str | None = None
        addendum_name: str | None = None
        addendum_value = config.get("instruction_addendum")
        if addendum_value is not None:
            addendum, error = _repo_path(
                repo_root, addendum_value, f"instruction_addendum for {tool_name!r}"
            )
            if error:
                errors.append(error)
                continue
            if addendum is None or not addendum.is_file():
                errors.append(f"Instruction addendum not found for {tool_name!r}: {addendum_value}")
                continue
            try:
                addendum_text = addendum.read_text(encoding="utf-8").rstrip()
            except OSError as exception:
                errors.append(f"Cannot read instruction addendum {addendum_value}: {exception}")
                continue
            addendum_name = addendum.relative_to(repo_root.resolve()).as_posix()

        for document_value in documents:
            document, error = _repo_path(
                repo_root, document_value, f"Generated doc for {tool_name!r}"
            )
            if error:
                errors.append(error)
                continue
            if document is None:
                continue
            if document == source:
                errors.append(f"Generated doc for {tool_name!r} cannot replace its canonical source")
                continue
            if document.is_symlink():
                errors.append(f"Generated doc is a symlink; refusing to follow it: {document_value}")
                continue
            if document in outputs:
                errors.append(f"Generated doc is declared more than once: {document_value}")
                continue
            sources = f"`{source_name}`"
            if addendum_name is not None:
                sources += f" and `{addendum_name}`"
            header = GENERATED_DOCS_HEADER.format(sources=sources)
            content = f"{header}\n\n{source_text}\n"
            if addendum_text:
                content += f"\n{addendum_text}\n"
            outputs[document] = content
    return outputs, errors


def _skill_globs(manifest: dict[str, object]) -> tuple[list[str], list[str]]:
    errors: list[str] = []
    roots: list[object] = [manifest.get("canonical_skills", ".agents/skills")]
    tools = manifest.get("tools", {})
    if not isinstance(tools, dict):
        return [], ["Manifest tools must be an object"]
    for tool_name, config in tools.items():
        if not isinstance(config, dict):
            errors.append(f"Manifest tool {tool_name!r} must be an object")
            continue
        if config.get("symlink_strategy", "none") != "none":
            skills_directory = config.get("skills_directory")
            if skills_directory:
                roots.append(skills_directory)

    globs: set[str] = set()
    for root in roots:
        if not isinstance(root, str) or not root:
            errors.append("Skill directories in the manifest must be non-empty paths")
            continue
        path = Path(root)
        if path.is_absolute() or ".." in path.parts:
            errors.append(f"Skill directory must stay inside the repository: {root}")
            continue
        globs.add(f"{path.as_posix().rstrip('/')}/**/*")
    return sorted(globs), errors


def _replace_skill_labeler_block(content: str, globs: list[str]) -> tuple[str | None, str | None]:
    lines = content.splitlines(keepends=True)
    starts = [index for index, line in enumerate(lines) if line.strip() == SKILL_LABELER_BEGIN]
    ends = [index for index, line in enumerate(lines) if line.strip() == SKILL_LABELER_END]
    if len(starts) != 1 or len(ends) != 1 or starts[0] >= ends[0]:
        return None, "labeler config must contain one ordered generated-skill marker pair"

    block = [
        SKILL_LABELER_BEGIN,
        "skills:",
        "  - changed-files:",
        "      - any-glob-to-any-file:",
        *[f"          - '{glob}'" for glob in globs],
        SKILL_LABELER_END,
    ]
    generated = "\n".join(block) + "\n"
    lines[starts[0] : ends[0] + 1] = generated.splitlines(keepends=True)
    return "".join(lines), None


def _generated_outputs(
    repo_root: Path, manifest: dict[str, object]
) -> tuple[dict[Path, str], list[str]]:
    outputs, errors = _instruction_outputs(repo_root, manifest)
    labeler_value = manifest.get("skill_labeler")
    if labeler_value is None:
        return outputs, errors
    labeler, error = _repo_path(repo_root, labeler_value, "skill_labeler")
    if error:
        errors.append(error)
        return outputs, errors
    if labeler is None or labeler.is_symlink() or not labeler.is_file():
        errors.append(f"Skill labeler config is missing or not a regular file: {labeler_value}")
        return outputs, errors
    globs, glob_errors = _skill_globs(manifest)
    errors.extend(glob_errors)
    try:
        content = labeler.read_text(encoding="utf-8")
    except OSError as exception:
        errors.append(f"Cannot read skill labeler config {labeler_value}: {exception}")
        return outputs, errors
    generated, error = _replace_skill_labeler_block(content, globs)
    if error:
        errors.append(f"{labeler_value}: {error}")
    elif generated is not None:
        outputs[labeler] = generated
    return outputs, errors


def validate_generated_surfaces(repo_root: Path, manifest: dict[str, object]) -> list[str]:
    """Reject drift in generated root instructions and manifest-derived labeler globs."""
    outputs, errors = _generated_outputs(repo_root, manifest)
    if errors:
        return errors
    for path, expected in outputs.items():
        if not path.is_file():
            errors.append(f"Generated surface missing: {path.relative_to(repo_root)}; run agent-surface.py sync")
            continue
        try:
            actual = path.read_text(encoding="utf-8")
        except OSError as exception:
            errors.append(f"Cannot read generated surface {path.relative_to(repo_root)}: {exception}")
            continue
        if actual != expected:
            errors.append(f"Generated surface drift: {path.relative_to(repo_root)}; run agent-surface.py sync")
    return errors


def sync_generated_surfaces(repo_root: Path, manifest: dict[str, object]) -> list[str]:
    """Create or repair only the generated surfaces explicitly declared in the manifest."""
    outputs, errors = _generated_outputs(repo_root, manifest)
    if errors:
        return errors
    for path in outputs:
        if path.is_symlink() or (path.exists() and not path.is_file()):
            errors.append(f"Generated surface is not a regular file: {path.relative_to(repo_root)}")
    if errors:
        return errors
    for path, content in outputs.items():
        try:
            if not path.is_file() or path.read_text(encoding="utf-8") != content:
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_text(content, encoding="utf-8")
        except OSError as exception:
            errors.append(f"Cannot write generated surface {path.relative_to(repo_root)}: {exception}")
    return errors
